// Carts with 10 or more lines get an extra 5% bulk discount.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  return Math.round(discounted);
}

arguments.new_string:
// Carts with 10 or more lines get an extra 5% bulk discount.
// Each discount applies once: the customer discount first, then the bulk
// discount. The result is rounded once, at the end.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const afterCustomerDiscount = subtotal * (1 - discount);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return Math.round(afterCustomerDiscount * (1 - bulk));
}

