---NEW
// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount.
// Each discount applies once: the customer discount first, then the bulk
// discount. The result is rounded once, at the end.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const afterCustomerDiscount = subtotal * (1 - discount);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return Math.round(afterCustomerDiscount * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
---TEST
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// A cart of `n` lines, each one item at `price`.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: the customer discount applies exactly once.
test('total applies the customer discount once (under 10 lines)', () => {
  // 1,000 - 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('total applies the 5% bulk discount once, after the customer discount (10 lines)', () => {
  // 10,000 - 10% = 9,000; 9,000 - 5% = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('total gives no bulk discount to a discounted 9-line cart', () => {
  // 9,000 - 10% = 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('total with discount rate 0 is only reduced by the bulk discount', () => {
  // 10,000 - 5% = 9,500
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(9, 1000), 0), 9000);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
